//! The starter list behind the Discover page: a short list of well-known apps bundled
//! with the store. Nobody has reviewed or endorsed them.
//!
//! Browsing must not cost API calls: an unauthenticated client gets 60 GitHub requests
//! an hour, and checking every featured app's releases would spend them before the user
//! clicks anything. So the index carries, per app, the platforms it ships for. It is a
//! plain JSON file that can be regenerated by CI and fetched from static hosting; the
//! copy compiled into the binary is the offline fallback.
//!
//! The index only decides what is *listed*. What is *offered for install* is always
//! decided from the live release, by the compatibility engine.

use crate::asset::classify;
use crate::compat::evaluate;
use crate::error::Result;
use crate::model::{AppId, AppSummary};
use crate::platform::{FormFactor, LinuxFamily, Platform};
use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct IndexEntry {
    /// `github:owner/repo` or `aur:package`.
    pub id: String,
    pub name: String,
    pub author: String,
    pub summary: String,
    pub category: String,
    /// `windows`, `linux`, `macos`, `android`, `ios`; for AUR entries `arch`.
    pub os: Vec<String>,
    /// Has a build meant for TVs (Android TV / leanback, or a couch-friendly desktop UI).
    #[serde(default)]
    pub tv: bool,
    /// File names of the latest release, when the index generator recorded them. With
    /// these the listing is decided by the same compatibility engine as installs, so
    /// "Linux" does not wrongly include, say, an AppImage-only app on Alpine. Without
    /// them the coarser `os` list is used.
    #[serde(default)]
    pub files: Vec<String>,
}

#[derive(Debug, Clone, Default, Deserialize)]
pub struct Index {
    pub apps: Vec<IndexEntry>,
}

#[derive(Debug, Clone)]
pub struct Section {
    pub title: String,
    pub apps: Vec<AppSummary>,
}

impl Index {
    pub fn from_json(json: &str) -> Result<Index> {
        Ok(serde_json::from_str(json)?)
    }

    /// The index compiled into the binary.
    pub fn bundled() -> Index {
        Index::from_json(include_str!("../data/index.json")).expect("bundled index is valid JSON")
    }

    fn listed_on(entry: &IndexEntry, p: &Platform) -> bool {
        if !entry.files.is_empty() {
            return entry.files.iter().filter_map(|f| classify(f)).any(|info| evaluate(&info, p).usable());
        }
        let is_arch = p.linux.as_ref().is_some_and(|l| l.family == LinuxFamily::Arch);
        entry.os.iter().any(|os| os == p.os.key() || (os == "arch" && is_arch))
    }

    /// What would be installed here, when the entry's file list allows saying so offline.
    fn install_label(entry: &IndexEntry, p: &Platform) -> Option<String> {
        entry
            .files
            .iter()
            .filter_map(|f| classify(f))
            .map(|info| (evaluate(&info, p), info))
            .filter(|(verdict, _)| verdict.usable())
            .max_by_key(|(verdict, _)| verdict.score)
            .map(|(_, info)| info.label())
    }

    /// Entries for this machine, grouped by category in first-appearance order.
    /// On a TV, apps made for TVs get their own row at the top.
    pub fn sections(&self, p: &Platform) -> Vec<Section> {
        let mut sections: Vec<Section> = Vec::new();
        let mut push = |title: &str, app: AppSummary| match sections.iter_mut().find(|s| s.title == title) {
            Some(s) => s.apps.push(app),
            None => sections.push(Section { title: title.to_string(), apps: vec![app] }),
        };
        let visible: Vec<(&IndexEntry, AppSummary)> = self
            .apps
            .iter()
            .filter(|e| Self::listed_on(e, p))
            .filter_map(|e| {
                let id = AppId::parse(&e.id)?;
                Some((
                    e,
                    AppSummary {
                        id,
                        name: e.name.clone(),
                        author: e.author.clone(),
                        summary: e.summary.clone(),
                        popularity: None,
                        homepage: String::new(),
                        license: None,
                        category: Some(e.category.clone()),
                        version: None,
                        install_label: Self::install_label(e, p),
                        warning: None,
                        origin: None,
                        installed_version: None,
                        rating: None,
                        icon_url: None,
                        downloads: None,
                        verified: false,
                        momentum: None,
                    },
                ))
            })
            .collect();
        if p.form_factor == FormFactor::Tv {
            for (e, app) in &visible {
                if e.tv {
                    push("Made for TV", app.clone());
                }
            }
        }
        for (e, app) in visible {
            // Already in the TV row; a ten-foot UI has no room for repeats.
            if p.form_factor == FormFactor::Tv && e.tv {
                continue;
            }
            // Nobody writes code from the sofa.
            if p.form_factor == FormFactor::Tv && e.category == "Developer tools" {
                continue;
            }
            push(&e.category, app);
        }
        sections
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_index_parses_and_ids_are_valid() {
        let index = Index::bundled();
        assert!(!index.apps.is_empty());
        for e in &index.apps {
            assert!(AppId::parse(&e.id).is_some(), "{}", e.id);
            assert!(!e.os.is_empty(), "{}", e.id);
        }
    }

    #[test]
    fn sections_are_filtered_by_platform() {
        let index = Index::from_json(
            r#"{"apps":[
              {"id":"github:a/win","name":"Win","author":"a","summary":"","category":"Tools","os":["windows"]},
              {"id":"github:a/droid","name":"Droid","author":"a","summary":"","category":"Media","os":["android"],"tv":true},
              {"id":"github:a/both","name":"Both","author":"a","summary":"","category":"Tools","os":["windows","android","linux"]},
              {"id":"aur:thing","name":"thing","author":"a","summary":"","category":"Tools","os":["arch"]}
            ]}"#,
        )
        .unwrap();
        let names = |preset: &str| -> Vec<(String, Vec<String>)> {
            index
                .sections(&Platform::preset(preset).unwrap())
                .into_iter()
                .map(|s| (s.title, s.apps.into_iter().map(|a| a.name).collect()))
                .collect()
        };
        assert_eq!(names("windows-x64"), vec![("Tools".to_string(), vec!["Win".to_string(), "Both".to_string()])]);
        assert_eq!(names("linux-x64-debian"), vec![("Tools".to_string(), vec!["Both".to_string()])]);
        assert_eq!(names("linux-x64-arch"), vec![("Tools".to_string(), vec!["Both".to_string(), "thing".to_string()])]);
        assert!(names("macos-arm64").is_empty());
        let tv = names("android-tv");
        assert_eq!(tv[0], ("Made for TV".to_string(), vec!["Droid".to_string()]));
    }
}
